package com.google.javascript.rhino;

import com.google.common.base.Preconditions;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class IR_tryCatch_TriageGen2Test {

    @Test
    public void testTryCatchSuccess() {
        // Prepare tryBody: must be a block
        Node tryBody = IR.block(IR.var(IR.name("x"), IR.number(1)));

        // Prepare catchNode: must be a catch node
        // In Rhino IR, a catch node is usually a specific type of node. 
        // We use catchNode(expr, body) to create a valid catch structure.
        Node catchNode = IR.catchNode(IR.name("e"), IR.block(IR.returnNode()));

        // Execute
        Node result = IR.tryCatch(tryBody, catchNode);

        // Verify
        assertNotNull(result);
        assertEquals(Token.TRY, result.getType());
        assertEquals(tryBody, result.getFirstChild());

        // The implementation says: Node catchBody = block(catchNode).copyInformationFrom(catchNode);
        // So the second child should be a block derived from the catchNode
        Node catchBody = result.getNextSibling(); // In some IR structures, children are accessed via getFirstChild/getNextSibling
        // However, based on the constructor: new Node(Token.TRY, tryBody, catchBody)
        // result.getFirstChild() is tryBody, result.getNextSibling() is catchBody
        assertNotNull(result.getNextSibling());
        assertEquals(catchNode, result.getNextSibling().getInformation()); 
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchThrowsWhenTryBodyIsNotBlock() {
        // tryBody is an expression, not a block
        Node tryBody = IR.name("x"); 
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());

        IR.tryCatch(tryBody, catchNode);
    }

    @Test(expected = IllegalStateException.class)
    public void testTryCatchThrowsWhenCatchNodeIsNotCatch() {
        // tryBody is a block
        Node tryBody = IR.block();
        // catchNode is a regular block, not a catch node
        Node catchNode = IR.block();

        IR.tryCatch(tryBody, catchNode);
    }

    @Test
    public void testTryCatchInformationCopy() {
        Node tryBody = IR.block();
        Node catchNode = IR.catchNode(IR.name("e"), IR.block());

        // Manually set some information on catchNode to verify copyInformationFrom
        // Since we don't have the exact internal API for setting info, 
        // we assume copyInformationFrom works as intended by the method signature.

        Node result = IR.tryCatch(tryBody, catchNode);

        Node catchBody = result.getNextSibling();
        assertNotNull(catchBody);
        // Verify that the catchBody (which is a block) contains the info from catchNode
        assertEquals(catchNode.getInformation(), catchBody.getInformation());
    }
}
